        "visit_start_text" = para_visit_start_text;

    DELETE FROM "Skills_Required_To_Fix"
    WHERE "skill_id" < para_skill_id;

    FOR rec IN SELECT * FROM "Engineer_Visits" LOOP
        FOR rec2 IN SELECT * FROM "Skills_Required_To_Fix" LOOP
            IF rec2."skill_id" > para_maintenance_contract_company_id THEN
                UPDATE "Maintenance_Contracts"
                SET "maintenance_contract_id" = "maintenance_contract_id" - para_maintenance_contract_id - 33;
            END IF;
        END LOOP;
    END LOOP;

    IF para_part_fault_id <> -1000 THEN
        UPDATE "Engineer_Visits"
        SET "engineer_id" = para_engineer_id;
    END IF;

    UPDATE "Fault_Log_Parts"
    SET "fault_status" = 'Fixed'
    WHERE "part_fault_id" = para_part_fault_id;

    UPDATE "Engineer_Visits" ev
    SET "fault_status" = 'Fixed'
    WHERE EXISTS
        (SELECT 1
        FROM "Fault_Log_Parts" flp
        WHERE flp."fault_log_entry_id" = ev."fault_log_entry_id"
          AND flp."part_fault_id" = para_part_fault_id
          AND flp."fault_status" = 'Fixed');
END;
$$;

